const repos = $input.first().json.value || [];
const incoming = $('Webhook - pr-complete').item.json.body || $('Webhook - pr-complete').item.json;
const repoName = incoming.repo || 'app';
const repo = repos.find(r => r.name === repoName);
if (!repo) throw new Error(`repo '${repoName}' not found`);
return [{ json: { repo_id: repo.id, repo_name: repoName, pr_id: incoming.pr_id, strategy: incoming.strategy || 'noFastForward', delete_source: !!incoming.delete_source, transition_work_items: !!incoming.transition_work_items, org: $env.AZDO_ORG_TRUSTWORKS || 'Trustworks', project: $env.AZDO_PROJECT_TRUSTWORKS || 'App' } }];

const r = $input.first().json;
const ctx = $('GET PR to refresh commit id').item.json;
if ((r.statusCode || 0) < 200 || (r.statusCode || 0) >= 300) {
  return [{ json: { _abort: true, upstream_status: r.statusCode, upstream_excerpt: (typeof r.body === 'string' ? r.body : JSON.stringify(r.body || {})).slice(0,500) } }];
}
const pr = r.body || r;
if (pr.status !== 'active') {
  return [{ json: { _abort: true, upstream_status: 409, upstream_excerpt: `PR status is '${pr.status}', not 'active'` } }];
}
const patchBody = {
  status: 'completed',
  lastMergeSourceCommit: { commitId: pr.lastMergeSourceCommit.commitId },
  completionOptions: {
    mergeStrategy: ctx.strategy,
    deleteSourceBranch: ctx.delete_source,
    transitionWorkItems: ctx.transition_work_items
  }
};
return [{ json: { ...ctx, patch: patchBody } }];

const r = $input.first().json;
const ctx = $('GET PR to refresh commit id').item.json;
if (ctx._abort) return [{ json: { status: 502, error: 'upstream-ado', upstream_status: ctx.upstream_status, upstream_excerpt: ctx.upstream_excerpt } }];
const status = r.statusCode || 0;
if (status >= 200 && status < 300) {
  const pr = r.body || r;
  const url = `https://dev.azure.com/${ctx.org}/${ctx.project}/_git/${ctx.repo_name}/pullrequest/${ctx.pr_id}`;
  const mc = (pr.lastMergeCommit && pr.lastMergeCommit.commitId) || null;
  return [{ json: { status: 200, pr_id: ctx.pr_id, url, merge_commit: mc, repo: ctx.repo_name } }];
}
let excerpt = '';
try { excerpt = typeof r.body === 'string' ? r.body : JSON.stringify(r.body); } catch(e) {}
if (excerpt.length > 500) excerpt = excerpt.slice(0, 500) + '...';
return [{ json: { status: 502, error: 'upstream-ado', upstream_status: status, upstream_excerpt: excerpt } }];
